(() => {
const HERO='data:image/webp;base64,';
const DETAIL='data:image/webp;base64,';
const IMG='data:image/webp;base64,';
function apply(){
 const main=document.querySelector('.main-media img');
 if(main){main.src=HERO;main.removeAttribute('onerror');main.alt='LUMORA red performance car';}
 const thumbs=[...document.querySelectorAll('.thumb img')];
 if(thumbs[0]) thumbs[0].src=HERO;
 if(thumbs[1]) thumbs[1].src=DETAIL;
 const title=document.querySelector('.detail h1');
 if(title) title.innerHTML='Demon Eye Headlight<span>Built for <b>Performance Cars</b></span>';
 const desc=document.querySelector('.detail .desc');
 if(desc) desc.textContent='A cinematic red performance-car showcase for LUMORA. Sharp LED eyes, glossy bodywork and an aggressive night-drive aesthetic.';
 const eyebrow=document.querySelector('.detail .eyebrow');
 if(eyebrow) eyebrow.textContent='DRIVE THE GLOW.';
 const crumbs=document.querySelector('.crumbs b');
 if(crumbs) crumbs.textContent='Red Performance Collection';
 const sku=document.querySelector('.sku');
 if(sku) sku.textContent='SKU: LM-CAR-001';
 const promoImgs=[...document.querySelectorAll('.promo img')];
 if(promoImgs[0]) promoImgs[0].src=DETAIL;
 if(promoImgs[1]) promoImgs[1].src=HERO;
 if(promoImgs[2]) promoImgs[2].src=DETAIL;
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',apply); else apply();
})();